variables.input:
timeseries r = sum(custom.nexus.log.adapter.responses), by: { nexus.cluster, nexus.service }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster)) and isNotNull(nexus.service)
| summarize n = count(), by: { nexus.service }
| fields service = nexus.service
| append [data record(service = "*")]
| sort service asc

timeseries r = sum(custom.nexus.log.adapter.responses), by: { nexus.cluster, nexus.service, nexus.channel }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster)) and ($Servicio == "*" or nexus.service == $Servicio) and isNotNull(nexus.channel)
| summarize n = count(), by: { nexus.channel }
| fields channel = nexus.channel
| append [data record(channel = "*")]
| sort channel asc

8.query:
timeseries r = sum(custom.nexus.log.adapter.responses), by: { nexus.cluster, nexus.service, nexus.channel, nexus.outcome }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster)) and ($Servicio == "*" or nexus.service == $Servicio) and (in("*", $Canal) or in(nexus.channel, $Canal))
| summarize responses = sum(r[]), by: { timeframe, interval, nexus.outcome }

9.query:
timeseries r = sum(custom.nexus.log.adapter.responses), by: { nexus.cluster, nexus.service, nexus.channel, nexus.outcome }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster)) and ($Servicio == "*" or nexus.service == $Servicio) and (in("*", $Canal) or in(nexus.channel, $Canal))
| filter nexus.outcome == "error"
| summarize errors = sum(r[]), by: { timeframe, interval, nexus.cluster }

12.query:
timeseries r = sum(custom.nexus.log.adapter.responses), by: { nexus.cluster, nexus.service, nexus.channel, nexus.http_code }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster)) and ($Servicio == "*" or nexus.service == $Servicio) and (in("*", $Canal) or in(nexus.channel, $Canal))
| fieldsAdd n = arraySum(r)
| summarize responses = sum(n), by: { nexus.http_code }
| sort responses desc

13.query:
timeseries m = sum(custom.nexus.log.adapter.mapping_errors), by: { nexus.cluster, nexus.service, nexus.channel, nexus.mapping.direction, nexus.mapping.field }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster)) and ($Servicio == "*" or nexus.service == $Servicio) and (in("*", $Canal) or in(nexus.channel, $Canal))
| fieldsAdd n = arraySum(m)
