16.query:
timeseries late_replies = sum(custom.nexus.log.adapter.stratus_late_replies), by: { nexus.cluster, nexus.component }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster))
| fieldsKeep timeframe, interval, nexus.component, late_replies

17.query:
timeseries avg_ms = avg(custom.nexus.log.adapter.backend_ms), by: { nexus.cluster, nexus.component }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster))
| fieldsKeep timeframe, interval, nexus.component, avg_ms

18.query:
timeseries c = sum(custom.nexus.log.adapter.backend_calls), by: { nexus.cluster, nexus.component, nexus.latency_bucket }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster))
| fieldsAdd n = arraySum(c)
| summarize calls = sum(n),
    slow_1s = sum(if(in(nexus.latency_bucket, array("1-5s", "5s+")), n, else: 0)),
    slow_5s = sum(if(nexus.latency_bucket == "5s+", n, else: 0)), by: { nexus.component }
| fieldsAdd pct_over_1s = round(100.0 * slow_1s / calls, decimals: 2),
            pct_over_5s = round(100.0 * slow_5s / calls, decimals: 2)
| lookup [
    timeseries m = max(custom.nexus.log.adapter.backend_ms), by: { nexus.component }
    | fieldsAdd max_ms = arrayMax(m)
  ], sourceField: nexus.component, lookupField: nexus.component, fields: { max_ms }
| sort pct_over_1s desc

19.query:
timeseries i = sum(custom.nexus.log.adapter.stream_issues), by: { nexus.cluster, nexus.component, nexus.kind, nexus.stream.attribute }
| filter (in("*", $Cluster) or in(nexus.cluster, $Cluster))
| fieldsAdd n = arraySum(i)
| summarize issues = sum(n), by: { nexus.component, nexus.kind, nexus.stream.attribute }
| sort issues desc
| limit 30

